class UnicodePiecewiseTranslation {
    /** @var string
     * @readonly */
    public $in;
    /** @var string
     * @readonly */
    public $out;
    /** @var list<int>
     * @readonly
     *
     * Sorted list of offsets, alternating out and in, starting with [0, 0]
     * and ending with a PHP_INT_MAX sentinel.
     * The character at `$this->out[$this->offsets[2*$i]]` corresponds to the
     * character at `$this->in[$this->offsets[2*$i+1]]`; characters up to the
     * next `out` position map one-to-one. */
    public $offsets;
    /** @var int */
    private $cursor = 0;

    function __construct($str) {
        $this->in = $str;
        $this->offsets = [0, 0];
        $pos = strcspn($str, UTF8_DEACCENT_LEAD);
        $len = strlen($str);
        if ($pos === $len) {
            $this->out = $str;
        } else {
            $pos0 = 0;
            $this->out = "";
            while ($pos !== $len) {
                $chlen = ord($str[$pos]) < 0xE0 ? 2 : 3;
                if (($r = UTF8_DEACCENT_MAP[substr($str, $pos, $chlen)] ?? null) !== null) {
                    $this->out .= substr($str, $pos0, $pos - $pos0) . $r;
                    $pos0 = $pos + $chlen;
                    $this->offsets[] = strlen($this->out);
                    $this->offsets[] = $pos0;
                }
                $pos += 1 + strcspn($str, UTF8_DEACCENT_LEAD, $pos + 1);
            }
            $this->out .= substr($str, $pos0);
        }
        $this->offsets[] = PHP_INT_MAX;
    }

    /** @param int $l      left edge of range, 0 <= $l < count($this->offsets)
     * @param int $r       right edge of range
     * @param int $pos     position being searched for
     * @param 0|1 $offset  whether `$pos` is out or in
     * @return int */
    private function segment_lower_bound($l, $r, $pos, $offset) {
        while ($l + 2 < $r) {
            $m = $l + ((($r - $l) >> 1) & ~1);
            $p = $this->offsets[$m + $offset];
            if ($pos < $p) {
                $r = $m;
            } else {
                $l = $m;
            }
        }
        return $l;
    }

    /** @param int $pos
     * @return int */
    function reverse($pos) {
        $i = $this->cursor;
        if ($pos < $this->offsets[$i]) {
            if ($i > 128) {
                $i = $this->segment_lower_bound(0, $i, $pos, 0);
            } else {
                $i = 0;
            }
        } else if (count($this->offsets) - $i > 128
                   && $pos > $this->offsets[$i + 10]) {
            $i = $this->segment_lower_bound($i, count($this->offsets) - 1, $pos, 0);
        }
        while ($pos >= $this->offsets[$i + 2]) {
            $i += 2;
        }
        $this->cursor = $i;
        return $this->offsets[$i + 1] + ($pos - $this->offsets[$i]);
    }
}

class UnicodeClusters {
    /** @var string */
    private $s;
    /** @var int */
    private $lbound;
    /** @var int */
    private $rbound;
    /** @var ?bool */
    private $ascii;

    /** @param string $s
     * @param ?int $lbound
     * @param ?int $rbound */
    function __construct($s, $lbound = null, $rbound = null) {
        if (!is_valid_utf8($s)) {
            $s = UnicodeHelper::utf8_replace_invalid($s, true);
            is_valid_utf8($s); // set "valid UTF-8" flag
        }
        $lbound = max(0, min($lbound ?? 0, strlen($s)));
        if ($lbound !== 0) {
            while ($lbound < strlen($s) && (ord($s[$lbound]) & 0xC0) === 0x80) {
                ++$lbound;
            }
        }
        $rbound = min(strlen($s), max($rbound ?? PHP_INT_MAX, $lbound));
        if ($rbound !== strlen($s)) {
            while ($rbound > $lbound && (ord($s[$rbound]) & 0xC0) === 0x80) {
                --$rbound;
            }
        }
        $this->s = $s;
        $this->lbound = $lbound;
        $this->rbound = $rbound;
    }

    /** @return $this */
    function analyze() {
        // scan short windows; otherwise glyphstep checks locally
        if ($this->ascii === null && $this->rbound - $this->lbound <= 512) {
            $this->ascii = !preg_match('/[\r\x80-\xFF]/', substr($this->s, $this->lbound, $this->rbound - $this->lbound));
        }
        return $this;
    }

    /** @param ?int $pos1
     * @param ?int $pos2
     * @param ?int $bound
     * @return int */
    function glyphlen($pos1 = null, $pos2 = null, $bound = null) {
        $pos1 = max($pos1 ?? 0, $this->lbound);
        $pos2 = min($pos2 ?? PHP_INT_MAX, $this->rbound);
        $bound = max(0, $bound ?? PHP_INT_MAX);
        if ($this->ascii || $pos2 - $pos1 < 2) {
            return min($pos2 - $pos1, $bound);
        } else if ($pos2 - $pos1 <= 64) {
            return min(preg_match_all('/\X/u', substr($this->s, $pos1, $pos2 - $pos1)), $bound);
        } else if ($bound < 1000
                   && $bound < $pos2 - $pos1
                   && preg_match("/[\\x00-\\x0C\\x0E-\\x7F]{" . ($bound + 1) . "}/A", $this->s, $m, 0, $pos1)) {
            return $bound;
        }
        $gl = 0;
        $step = min((int) (($pos2 - $pos1) / 2), $bound);
        while (true) {
            if ($step === 0
                || !preg_match("/\\X{{$step}}/Au", $this->s, $m, 0, $pos1)) {
                if ($step <= 1) {
                    return $gl;
                }
            } else if ($pos1 + strlen($m[0]) < $pos2) {
                $gl += $step;
                $pos1 += strlen($m[0]);
                $step = min($step, $bound - $gl);
                continue;
            } else if ($pos1 + strlen($m[0]) === $pos2 || $step === 1) {
                return $gl + $step;
            }
            $step = min((int) ($step / 2), $bound - $gl);
        }
    }

    /** @param int $pos
     * @param int $n
     * @return int */
    function glyphstep($pos, $n) {
        if ($n === 0 || $this->ascii) {
            return min(max($pos + $n, $this->lbound), $this->rbound);
        } else if ($n > 0) {
            if ($pos + $n >= $this->rbound) {
                return $this->rbound;
            }
            // fast path: n+1 ASCII bytes other than CR
            $k = $n + 1;
            if (preg_match("/[\\x00-\\x0C\\x0E-\\x7F]{{$k}}|(\\X{{$n}})/Au", $this->s, $m, 0, $pos)) {
                return isset($m[1]) ? min($pos + strlen($m[1]), $this->rbound) : $pos + $n;
            }
            return $this->rbound;
        }
        $n = -$n;
        if ($pos - $n <= $this->lbound) {
            return $this->lbound;
        }
        // fast path: n+1 ASCII bytes other than CR
        $k = $n + 1;
        if (preg_match("/[\\x00-\\x0C\\x0E-\\x7F]{{$k}}/A", $this->s, $m, 0, $pos - $k)) {
            return $pos - $n;
        }
        // Look back through doubling windows, giving up at 36 bytes/glyph.
        // A window that starts inside a cluster can mis-split its first two
        // \X matches (e.g., at a ZWJ), so boundaries are trusted only after
        // the second match, unless the window starts at the left bound.
        $limit = max($this->lbound, $pos - 36 * $n);
        $width = 2 * $n + 8;
        while (true) {
            $p1 = max($limit, $pos - $width);
            while ($p1 > $this->lbound && (ord($this->s[$p1]) & 0xC0) === 0x80) {
                --$p1;
            }
            $nm = preg_match_all('/\X/u', substr($this->s, $p1, $pos - $p1));
            if ($nm - $n >= ($p1 === $this->lbound ? 0 : 2)) {
                $skip = $nm - $n;
            } else if ($p1 === $this->lbound) {
                return $this->lbound;
            } else if ($p1 <= $limit) {
                $skip = min($nm, 2); // farthest trusted boundary
            } else {
                // size the next window from this one's bytes per glyph
                $width = max(2 * $width, (int) ceil(($pos - $p1) / max($nm, 1) * ($n + 4)));
                continue;
            }
            if ($skip > 0) {
                preg_match("/\\X{{$skip}}/Au", $this->s, $m, 0, $p1);
                $p1 += strlen($m[0]);
            }
            return $p1;
        }
    }
}

class UnicodeHelper {
    /** @readonly */
    public static $f_ligature_map = [
        "ﬀ" => "ff", "ﬁ" => "fi", "ﬂ" => "fl", "ﬃ" => "ffi", "ﬄ" => "ffl"
    ];

    /** @var array<string,Transliterator|false> */
    private static $search_tr = [];

    /** @param string $str
     * @return ?string */
    static function maybe_deaccent($str) {
        $pos = strcspn($str, UTF8_DEACCENT_LEAD);
        $len = strlen($str);
        if ($pos === $len) {
            return null;
        }
        $pos0 = 0;
        $out = "";
        while ($pos !== $len) {
            $chlen = ord($str[$pos]) < 0xE0 ? 2 : 3;
            if (($r = UTF8_DEACCENT_MAP[substr($str, $pos, $chlen)] ?? null) !== null) {
                $out .= substr($str, $pos0, $pos - $pos0) . $r;
                $pos0 = $pos + $chlen;
            }
            $pos += 1 + strcspn($str, UTF8_DEACCENT_LEAD, $pos + 1);
        }
        if ($pos0 === 0) {
            return null;
        }
        $out .= substr($str, $pos0);
        return $out;
    }

    /** @param string $s
     * @return string */
    static function deaccent($s) {
        return self::maybe_deaccent($s) ?? $s;
    }

    /** @param string $s
     * @return UnicodePiecewiseTranslation */
    static function deaccent_offsets($s) {
        return new UnicodePiecewiseTranslation($s);
    }

    /** @param string $str
     * @return string */
    static function normalize($str) {
        return normalizer_normalize($str);
    }

    /** Remove Unicode bidirectional formatting characters.
     *
     * These reorder the text a reader sees without changing the bytes, so a
     * name carrying them can display as some other name. Use on any name that
     * arrived from outside and is shown as an identity.
     * @param string $str
     * @return string */
    static function strip_bidi($str) {
        // U+061C, U+200E-200F, U+202A-202E, U+2066-2069
        return preg_replace('/\xD8\x9C|\xE2\x80[\x8E\x8F\xAA-\xAE]|\xE2\x81[\xA6-\xA9]/', "", $str);
    }

    /** @param 'UTF-8'|'Windows-1252'|'UTF-16LE'|'UTF-16BE' $encoding
     * @param string $s
     * @return string */
    static function to_utf8($encoding, $s) {
        if ($encoding === "Windows-1252") {
            $encoding = "ibm-5348_P100-1997";
        }
        return (new UConverter("UTF-8", $encoding))->convert($s);
    }

    /** @param string $str
     * @param int $pos
     * @return string */
    static function utf8_char_at($str, $pos) {
        $len = strlen($str);
        $ch = ord($str[$pos]);
        if ($ch < 0x80) {
            return $str[$pos];
        } else if ($ch < 0xC2
                   || $ch > 0xF4
                   || $pos + 1 >= $len) {
            return "";
        }
        $ch1 = ord($str[$pos + 1]);
        if (($ch1 & 0xC0) !== 0x80
            || ($ch === 0xE0 && $ch1 < 0xA0)  // overlong
            || ($ch === 0xED && $ch1 >= 0xA0) // surrogate
            || ($ch === 0xF0 && $ch1 < 0x90)  // overlong
            || ($ch === 0xF4 && $ch1 >= 0x90)) { // invalid
            return "";
        } else if ($ch < 0xE0) {
            return substr($str, $pos, 2);
        } else if ($pos + 2 >= $len
                   || (ord($str[$pos + 2]) & 0xC0) !== 0x80) {
            return "";
        } else if ($ch < 0xF0) {
            return substr($str, $pos, 3);
        } else if ($pos + 3 >= $len
                   || (ord($str[$pos + 3]) & 0xC0) !== 0x80) {
            return "";
        }
        return substr($str, $pos, 4);
    }

    /** @param string $str
     * @return int */
    static function utf8_ord($str, $pos = 0) {
        $len = strlen($str);
        $ch = ord($str[$pos]);
        if ($ch < 0x80) {
            return $ch;
        } else if ($ch < 0xC2
                   || $ch > 0xF4
                   || $pos + 1 >= $len) {
            return -1;
        }
        $ch1 = ord($str[$pos + 1]);
        if (($ch1 & 0xC0) !== 0x80
            || ($ch === 0xE0 && $ch1 < 0xA0)  // overlong
            || ($ch === 0xED && $ch1 >= 0xA0) // surrogate
            || ($ch === 0xF0 && $ch1 < 0x90)  // overlong
            || ($ch === 0xF4 && $ch1 >= 0x90)) { // invalid
            return -1;
        } else if ($ch < 0xE0) {
            return (($ch & 0x1F) << 6) | ($ch1 & 0x3F);
        } else if ($pos + 2 >= $len) {
            return -1;
        }
        $ch2 = ord($str[$pos + 2]);
        if (($ch2 & 0xC0) !== 0x80) {
            return -1;
        } else if ($ch < 0xF0) {
            return (($ch & 0x0F) << 12) | (($ch1 & 0x3F) << 6) | ($ch2 & 0x3F);
        } else if ($pos + 3 >= $len) {
            return -1;
        }
        $ch3 = ord($str[$pos + 3]);
        if (($ch3 & 0xC0) !== 0x80) {
            return -1;
        }
        return (($ch & 0x07) << 18) | (($ch1 & 0x3F) << 12) | (($ch2 & 0x3F) << 6) | ($ch3 & 0x3F);
    }

    /** @param int $ch
     * @return list<int> */
    static function utf16_seq($ch) {
        if ($ch >= 0 && $ch <= 0xFFFF) {
            return [$ch];
        } else if ($ch >= 0x10000 && $ch <= 0x10FFFF) {
            $ch -= 0x10000;
            return [0xD800 | ($ch >> 10), 0xDC00 | ($ch & 0x3FF)];
        }
        return [];
    }

    /** @param int $ch
     * @return string */
    static function utf8_chr($ch) {
        assert($ch >= 0 && $ch <= 0x10FFFF);
        if ($ch < 0x80) {
            return chr($ch);
        } else if ($ch < 0x800) {
            return chr(0xC0 | ($ch >> 6)) . chr(0x80 | ($ch & 0x3F));
        } else if ($ch < 0x10000) {
            return chr(0xE0 | ($ch >> 12)) . chr(0x80 | (($ch >> 6) & 0x3F)) . chr(0x80 | ($ch & 0x3F));
        } else {
            return chr(0xF0 | ($ch >> 18)) . chr(0x80 | (($ch >> 12) & 0x3F)) . chr(0x80 | (($ch >> 6) & 0x3F)) . chr(0x80 | ($ch & 0x3F));
        }
    }

    /** @param int $ch
     * @return 1|2|3|4 */
    static function utf8_chrlen($ch) {
        assert($ch >= 0 && $ch <= 0x10FFFF);
        return 1 + (int) ($ch >= 0x80) + (int) ($ch >= 0x800) + (int) ($ch >= 0x10000);
    }

    /** @param string $str
     * @return string */
    static function utf8_to_html_entities($str, $flag = ENT_NOQUOTES) {
        if ($flag & ENT_IGNORE) {
            $start = "";
        } else if (($flag & ENT_QUOTES) === ENT_QUOTES) {
            $start = "&<>\"'";
        } else if (($flag & ENT_COMPAT) === ENT_COMPAT) {
            $start = "&<>\"";
        } else {
            $start = "&<>";
        }
        $flag = ($flag & (ENT_HTML401 | ENT_XML1 | ENT_XHTML | ENT_HTML5)) | ENT_QUOTES;
        return preg_replace_callback('/[' . $start . '\200-\377][\200-\277]*/',
                                     function ($m) use ($flag) {
            if (($f = UnicodeHelper::$f_ligature_map[$m[0]] ?? null)) {
                return $f;
            }
            $e = htmlentities($m[0], $flag, "UTF-8");
            if (substr($e, 0, 1) !== "&") {
                $n = ord($m[0][0]);
                if ($n < 0xE0) {
                    $n &= 0x1F;
                } else if ($n < 0xF0) {
                    $n &= 0x0F;
                } else {
                    $n &= 0x07;
                }
                for ($i = 1; $i < strlen($m[0]); ++$i) {
                    $n = ($n << 6) | (ord($m[0][$i]) & 0x3F);
                }
                $e = "&#" . $n . ";";
            }
            return $e;
        }, $str);
    }

    /** @param string $str
     * @return string */
    static function utf8_to_xml_numeric_entities($str, $flag = ENT_NOQUOTES) {
        if ($flag & ENT_IGNORE) {
            $start = "";
        } else if (($flag & ENT_QUOTES) === ENT_QUOTES) {
            $start = "&<>\"'";
        } else if (($flag & ENT_COMPAT) === ENT_COMPAT) {
            $start = "&<>\"";
        } else {
            $start = "&<>";
        }
        return preg_replace_callback('/[' . $start . '\200-\377][\200-\277]*/',
                                     function ($m) {
            if (($f = UnicodeHelper::$f_ligature_map[$m[0]] ?? null)) {
                return $f;
            } else {
                $n = ord($m[0][0]);
                if ($n < 0x80) {
                    // do nothing
                } else if ($n < 0xE0) {
                    $n &= 0x1F;
                } else if ($n < 0xF0) {
                    $n &= 0x0F;
                } else {
                    $n &= 0x07;
                }
                for ($i = 1; $i < strlen($m[0]); ++$i) {
                    $n = ($n << 6) | (ord($m[0][$i]) & 0x3F);
                }
                return "&#" . $n . ";";
            }
        }, $str);
    }

    /** @param string $str
     * @param ?int $lbound
     * @param ?int $rbound
     * @return UnicodeClusters */
    static function utf8_clusters($str, $lbound = null, $rbound = null) {
        return new UnicodeClusters($str, $lbound, $rbound);
    }

    /** @param string $str
     * @return int */
    static function utf8_glyphlen($str) {
        return preg_match_all('/\X/u', $str);
    }

    /** @param string $str
     * @return int */
    static function utf16_strlen($str) {
        return strlen($str) - preg_match_all('/[\xC0-\xDF]|[\xE0-\xEF][\x80-\xBF]|[\xF0-\xF7][\x80-\xBF]/', $str);
    }

    /** @param string $str
     * @param int $len  maximum prefix length; > 65535 means ∞
     * @return string|false */
    static function utf8_prefix($str, $len) {
        if ($len > 65535) {
            return is_valid_utf8($str) ? $str : false;
        }
        preg_match('/\A\X{0,' . $len . '}+/u', $str, $m);
        return isset($m[0]) ? $m[0] : false;
    }

    /** @param string $str
     * @param int $len  maximum length in Unicode grapheme clusters; > 65535 means ∞
     * @param int $suffix_len
     * @return string */
    static function utf8_char_abbreviate($str, $len, $suffix_len = 0) {
        if ($len > 65535) {
            return $str;
        }
        preg_match('/\A(\X{0,' . max($len - 3, 0) . '}+)\X{0,3}+/u', $str, $m);
        if (!isset($m[0])) {
            return str_repeat(".", $len);
        } else if (strlen($m[0]) === strlen($str)) {
            return $str;
        } else if ($len <= 3) {
            return str_repeat(".", max($len, 0));
        } else if ($suffix_len <= 0) {
            return $m[1] . "...";
        }
        preg_match('/\A(\X{' . max($len - $suffix_len - 3, 0) . '})\X*?(\X{' . min($suffix_len, $len - 3) . '})\z/u', $str, $m);
        if (!isset($m[0])) {
            return str_repeat(".", $len);
        }
        return $m[1] . "..." . $m[2];
    }

    /** @param string $str
     * @param int $len  maximum prefix length in Unicode grapheme clusters; > 65535 means ∞
     * @return string|false */
    static function utf8_word_prefix($str, $len) {
        if (strlen($str) <= $len || $len > 65535) {
            return is_valid_utf8($str) ? $str : false;
        }
        // possessive matches only: backtracking into `\X` is quadratic on
        // long clusters (e.g., thousands of combining marks)
        // `$m[1]` is the first `$len` clusters; `$m[0]` adds one character
        $mok = preg_match('/\A(\X{1,' . max($len, 1) . '}+).?/su', $str, $m);
        if ($mok === false) { // input string was not UTF-8 -- should not happen!
            return false;
        } else if ($mok === 0 || strlen($m[1]) === strlen($str)) {
            return $str;
        }
        // If `$m[1]` contains a word break, return through the last one,
        // i.e., up to the last space run that follows a non-space
        if (preg_match('/\A(?:[^\pZ\s]*+([\pZ\s]++))++/u', $m[0], $mm)
            && strlen($mm[0]) !== strlen($mm[1])) {
            return substr($str, 0, strlen($mm[0]) - strlen($mm[1]));
        }
        // Otherwise, complete its last word
        if (preg_match('/\G[^\pZ\s]++/u', $str, $mm, 0, strlen($m[1]))) {
            return $m[1] . $mm[0];
        }
        return $m[1];
    }

    /** @param string $str
     * @param int $len
     * @return string */
    static function utf8_word_abbreviate($str, $len) {
        $pfx = self::utf8_word_prefix($str, $len);
        if ($pfx === false) { // input string was not UTF-8 -- should not happen!
            $str = convert_to_utf8($str);
            $pfx = self::utf8_word_prefix($str, $len);
        }
        if (strlen($pfx) === strlen($str)) {
            return $str;
        }
        return "{$pfx}...";
    }

    /** @param string &$str
     * @param int $len
     * @param bool $preserve_space
     * @return string|false */
    static function utf8_line_break(&$str, $len, $preserve_space = false) {
        if ($str === "") {
            return false;
        }
        $line = self::utf8_word_prefix($str, $len);
        if ($line === false) { // input string was not UTF-8 -- should not happen!
            $str = convert_to_utf8($str);
            $line = self::utf8_word_prefix($str, $len);
        }
        if (($nl = strpos($line, "\n")) !== false) {
            $line = substr($line, 0, $nl);
        }
        $pos = strlen($line);
        if (preg_match('/\G(?:\pZ|[\t\f\r])*\n?/u', $str, $m, 0, $pos)) {
            $pos += strlen($m[0]);
        }
        if ($preserve_space && $pos !== strlen($line)) {
            $ends_nl = $str[$pos - 1] === "\n" ? 1 : 0;
            $line .= substr($str, strlen($line), $pos - strlen($line) - $ends_nl);
        }
        $str = substr($str, $pos);
        return $line;
    }

    /** @param string $str
     * @param int $len
     * @param bool $preserve_space
     * @return array{string|false,string} */
    static function utf8_line_break_parts($str, $len, $preserve_space = false) {
        $line = self::utf8_line_break($str, $len, $preserve_space);
        return [$line, $str];
    }

    /** Like `utf8_line_break`, but a word longer than `$len` is broken at
     * `$len` rather than overflowing the line.
     * @param string &$str
     * @param int $len
     * @param bool $preserve_space
     * @return string|false */
    static function utf8_hard_line_break(&$str, $len, $preserve_space = false) {
        if ($str === "") {
            return false;
        }
        $line = self::utf8_prefix($str, $len);
        if ($line === false) {
            $str = convert_to_utf8($str);
            $line = self::utf8_prefix($str, $len);
        }
        if (($nl = strpos($line, "\n")) !== false) {
            $line = substr($line, 0, $nl);
        } else if (strlen($line) !== strlen($str)) {
            if (preg_match('/\G(?!\pZ|\s)/u', $str, $m, 0, strlen($line))) {
                // The cut falls inside a word (a non-space follows). Back up to
                // the last break point in the line, dropping the partial word;
                // with none (a single word wider than `$len`) the hard cut at
                // `$len` stands.
                $line = preg_replace('/(?:\pZ|\s)+(?:(?!\pZ|\s)\X)*+\z/u', "", $line, 1);
            } else {
                // The cut falls at a word boundary; just drop trailing space.
                $line = preg_replace('/(?:\pZ|\s)+\z/u', "", $line, 1);
            }
        }
        $pos = strlen($line);
        if (preg_match('/\G(?:\pZ|[\t\f\r])*\n?/u', $str, $m, 0, $pos)) {
            $pos += strlen($m[0]);
        }
        if ($preserve_space && $pos !== strlen($line)) {
            $ends_nl = $str[$pos - 1] === "\n" ? 1 : 0;
            $line .= substr($str, strlen($line), $pos - strlen($line) - $ends_nl);
        }
        $str = substr($str, $pos);
        return $line;
    }

    /** @param string $str
     * @param int $len
     * @param bool $preserve_space
     * @return array{string|false,string} */
    static function utf8_hard_line_break_parts($str, $len, $preserve_space = false) {
        $line = self::utf8_hard_line_break($str, $len, $preserve_space);
        return [$line, $str];
    }

    /** @param string $str
     * @return string */
    static function demojibake($str) {
        return preg_replace_callback('/\xC3[\x80-\x8F]\xC2[\x80-\xBF]/', function ($m) {
            return chr(ord(substr($m[0], 1, 1)) + 0x40) . substr($m[0], 3, 1);
        }, $str);
    }

    /** @param string $str
     * @return string */
    static function remove_f_ligatures($str) {
        return preg_replace_callback("/\xEF\xAC[\x80-\x84]/", function ($m) {
            return UnicodeHelper::$f_ligature_map[$m[0]];
        }, $str);
    }

    /** @param string $str
     * @param int $len
     * @return string */
    static function utf8_truncate($str, $len) {
        return self::utf8_truncate_invalid(substr($str, 0, $len));
    }

    /** @param string $str
     * @return 0|1|2|3 */
    static function utf8_incomplete_suffix_length($str) {
        $len = strlen($str);
        $c = $len ? ord($str[$len - 1]) : 0;
        if ($c < 0x80) {
            return 0;
        } else if ($c >= 0xC0
                   || $len === 1
                   || ($d = ord($str[$len - 2])) < 0x80) {
            return 1;
        } else if ($d >= 0xC0
                   && $d < 0xE0) {
            return 0;
        } else if ($d >= 0xC0
                   || $len === 2
                   || ($e = ord($str[$len - 3])) < 0x80) {
            return 2;
        } else if ($e >= 0xE0
                   && $e < 0xF0) {
            return 0;
        } else if ($e >= 0xC0
                   || $len === 3
                   || ord($str[$len - 4]) < 0xF0) {
            return 3;
        } else {
            return 0;
        }
    }

    /** @param string $str
     * @param bool $is_le
     * @return 0|1|2|3 */
    static function utf16_incomplete_suffix_length($str, $is_le) {
        $len = strlen($str);
        $keep = $len & 1;
        if ($len - $keep > 0) {
            $ch = ord($str[$len - $keep - ($is_le ? 1 : 2)]);
            if ($ch >= 0xD8 && $ch < 0xDC) {
                $keep += 2;
            }
        }
        return $keep;
    }

    /** @param string $str
     * @return string */
    static function utf8_truncate_invalid($str) {
        $slen = self::utf8_incomplete_suffix_length($str);
        return $slen === 0 ? $str : substr($str, 0, strlen($str) - $slen);
    }

    /** @param string $str
     * @param bool $keep_offsets
     * @return string */
    static function utf8_replace_invalid($str, $keep_offsets = false) {
        if (!$keep_offsets) {
            return self::to_utf8("UTF-8", $str);
        }
        return preg_replace('/(?:[\xC2-\xDF][\x80-\xBF]|\xE0[\xA0-\xBF][\x80-\xBF]|[\xE1-\xEC\xEE\xEF][\x80-\xBF]{2}|\xED[\x80-\x9F][\x80-\xBF]|\xF0[\x90-\xBF][\x80-\xBF]{2}|[\xF1-\xF3][\x80-\xBF]{3}|\xF4[\x80-\x8F][\x80-\xBF]{2})(*SKIP)(*FAIL)|[\x80-\xFF]/', "?", $str);
    }

    /** Return the offset of the first byte that is not part of a valid UTF-8
     * sequence, or `false` if `$str` is valid UTF-8.
     * @param string $str
     * @return int|false */
    static function utf8_invalid_offset($str) {
        if (preg_match('//u', $str)) {
            return false;
        }
        preg_match('/\A(?:[\x00-\x7F]|[\xC2-\xDF][\x80-\xBF]|\xE0[\xA0-\xBF][\x80-\xBF]|[\xE1-\xEC\xEE\xEF][\x80-\xBF]{2}|\xED[\x80-\x9F][\x80-\xBF]|\xF0[\x90-\xBF][\x80-\xBF]{2}|[\xF1-\xF3][\x80-\xBF]{3}|\xF4[\x80-\x8F][\x80-\xBF]{2})*+\K/', $str, $m, PREG_OFFSET_CAPTURE);
        return $m[0][1];
    }
}
